package com.pawmatch.inference.baseline;

import java.util.List;

/**
 * User-facing Ukrainian texts of {@code pawmatch-baseline-1.0.0}, verbatim from the Python reference. Explanations are
 * generated by the model (they depend on breed and profile values), so they stay on the backend.
 * Any change here is a change to the model's output and must be reflected in the parity goldens.
 */
final class BaselineTexts {

    static final String MODEL_VERSION = "pawmatch-baseline-1.0.0";
    static final String MODEL_TYPE = "weighted_rule_based_baseline";
    static final String SCORE_MEANING = "Індекс відповідності за оціненими критеріями, не ймовірність успіху.";

    static final String LABEL_ACTIVITY = "Активність";
    static final String LABEL_SHEDDING = "Линяння";
    static final String LABEL_GROOMING = "Догляд за шерстю";
    static final String LABEL_MENTAL_STIMULATION = "Розумові заняття";
    static final String LABEL_BARKING = "Вокалізація";
    static final String LABEL_SIZE = "Розмір";
    static final String LABEL_YOUNG_CHILDREN = "Взаємодія з малими дітьми";
    static final String LABEL_OTHER_DOGS = "Взаємодія з іншими собаками";

    static final String EXCLUDED_SIZE = "Розмір поза явно дозволеним списком.";
    static final String EXCLUDED_YOUNG_CHILDREN = "Оцінка взаємодії з малими дітьми нижча за поріг прототипу 3/5.";
    static final String EXCLUDED_OTHER_DOGS = "Оцінка взаємодії з іншими собаками нижча за поріг прототипу 3/5.";

    static final String WARNING_TENDENCIES =
            "Породні оцінки описують тенденції; поведінка конкретної собаки може відрізнятися.";
    static final String WARNING_CHILDREN_SUPERVISION =
            "Навіть висока породна оцінка не замінює нагляду дорослого при взаємодії з дітьми.";
    static final String WARNING_CATS = "Взаємодію з котами не оцінено: у каталозі немає підтверджених даних.";

    static final String NOTICE_DEFAULT = "Порівняйте потреби рекомендованих порід перед вибором.";

    static final List<String> UNASSESSED = List.of(
            "Час прогулянок: немає перевірених породних норм у хвилинах.",
            "Години самотності: немає перевірених породних меж.",
            "Час навчання та досвід власника: не підміняються оцінкою trainability.",
            "Тип житла: придатність не виводиться лише з розміру породи.");
    static final String UNASSESSED_CATS = "Взаємодія з котами: підтверджені породні дані відсутні.";

    private BaselineTexts() {
    }

    static String excludedHardLimit(String criterion, int rating, int maximum) {
        return criterion + ": оцінка " + rating + " перевищує жорстку межу " + maximum + ".";
    }

    static String activity(int breed, int wanted) {
        return "Активність породи — " + breed + "/5, бажаний рівень — " + wanted + "/5.";
    }

    static String capacity(String label, int breed, int limit) {
        return label + ": оцінка породи — " + breed + "/5, ваша допустима межа — " + limit + "/5.";
    }

    static String size(String breedSize, String wantedSize) {
        return "Розмір за AKC — " + breedSize + "; бажаний — " + wantedSize + ".";
    }

    static String compatibility(String label, int breed) {
        return label + ": породна оцінка " + breed + "/5; потрібна оцінка конкретної собаки та нагляд.";
    }

    static String noticeFewer(int count) {
        return "Знайдено лише " + count + " порід вище порога; слабкі варіанти не додавалися.";
    }
}
